def button_bom_cost(self):
    templates = self.filtered(lambda t: t.product_variant_count == 1 and t.bom_count > 0)
    if templates:
        return templates.mapped('product_variant_id').button_bom_cost()

def _set_price_from_bom(self, boms_to_recompute=False):
    self.ensure_one()
    bom = self.env['mrp.bom']._bom_find(self)[self]
    if bom:
        self.standard_price = self._compute_bom_price(bom, boms_to_recompute=boms_to_recompute)
    else:
        bom = self.env['mrp.bom'].search([('byproduct_ids.product_id', '=', self.id)], order='sequence, product_id, id', limit=1)
        if bom:
            price = self._compute_bom_price(bom, boms_to_recompute=boms_to_recompute, byproduct_bom=True)
            if price:
                self.standard_price = price

def _compute_bom_price(self, bom, boms_to_recompute=False, byproduct_bom=False):
    self.ensure_one()
    if not bom:
        return 0
    if not boms_to_recompute:
        boms_to_recompute = []
    total = 0
    for opt in bom.operation_ids:
        if opt._skip_operation_line(self):
            continue
        duration_expected = opt.workcenter_id._get_expected_duration(self) + opt.time_cycle * 100 / opt.workcenter_id.time_efficiency
        total += duration_expected / 60 * opt._total_cost_per_hour()
    for line in bom.bom_line_ids:
        if line._skip_bom_line(self):
            continue
        if line.child_bom_id and line.child_bom_id in boms_to_recompute:
            child_total = line.product_id._compute_bom_price(line.child_bom_id, boms_to_recompute=boms_to_recompute)
            total += line.product_id.uom_id._compute_price(child_total, line.product_uom_id) * line.product_qty
        else:
            total += line.product_id.uom_id._compute_price(line.product_id.standard_price, line.product_uom_id) * line.product_qty
    if byproduct_bom:
        byproduct_lines = bom.byproduct_ids.filtered(lambda b: b.product_id == self and b.cost_share != 0)
        product_uom_qty = 0
        for line in byproduct_lines:
            product_uom_qty += line.product_uom_id._compute_quantity(line.product_qty, self.uom_id, round=False)
        byproduct_cost_share = sum(byproduct_lines.mapped('cost_share'))
        if byproduct_cost_share and product_uom_qty:
            return total * byproduct_cost_share / 100 / product_uom_qty
    else:
        byproduct_cost_share = sum(bom.byproduct_ids.mapped('cost_share'))
        if byproduct_cost_share:
            total *= float_round(1 - byproduct_cost_share / 100, precision_rounding=0.0001)
        return bom.product_uom_id._compute_price(total / bom.product_qty, self.uom_id)

def product_price_update_before_done(self, forced_qty=None):
    tmpl_dict = defaultdict(lambda : 0.0)
    std_price_update = {}
    for move in self:
        if not move._is_in():
            continue
        if move.with_company(move.company_id).product_id.cost_method == 'standard':
            continue
        product_tot_qty_available = move.product_id.sudo().with_company(move.company_id).quantity_svl + tmpl_dict[move.product_id.id]
        rounding = move.product_id.uom_id.rounding
        valued_move_lines = move._get_in_move_lines()
        quantity = sum(valued_move_lines.mapped('quantity_product_uom'))
        qty = forced_qty or quantity
        if float_is_zero(product_tot_qty_available, precision_rounding=rounding):
            new_std_price = move._get_price_unit()
        elif float_is_zero(product_tot_qty_available + move.product_qty, precision_rounding=rounding) or float_is_zero(product_tot_qty_available + qty, precision_rounding=rounding):
            new_std_price = move._get_price_unit()
        else:
            amount_unit = std_price_update.get((move.company_id.id, move.product_id.id)) or move.product_id.with_company(move.company_id).standard_price
            new_std_price = (amount_unit * product_tot_qty_available + move._get_price_unit() * qty) / (product_tot_qty_available + qty)
        tmpl_dict[move.product_id.id] += quantity
        move.product_id.with_company(move.company_id.id).with_context(disable_auto_svl=True).sudo().write({'standard_price': new_std_price})
        std_price_update[move.company_id.id, move.product_id.id] = new_std_price

def _compute_price(self, price, to_unit):
    self.ensure_one()
    if not self or not price or (not to_unit) or (self == to_unit):
        return price
    if self.category_id.id != to_unit.category_id.id:
        return price
    amount = price * self.factor
    if to_unit:
        amount = amount / to_unit.factor
    return amount

@api.depends('bom_line_ids.product_id', 'product_qty')
def _compute_bom_cost(self):
    """Compute total cost per unit"""
    for rec in self:
        cost_mapp = rec.bom_line_ids.mapped('cost')
        rec.bom_cost = sum(cost_mapp)
        rec.total_bom_cost = rec.bom_cost * rec.product_qty

@api.onchange('product_qty', 'product_id')
def _onchange_product_id(self):
    """ Computing total cost of each component"""
    self.cost = self.product_id.standard_price * self.product_qty
